-- ============================================================================
-- FIX the Morning Market load (decided 2026-11-27). Generated by
-- scripts/build_mm_seed.py; do not edit by hand.
--
-- The first reset used column E of the case workbook as the opening stock.
-- Column E (ຂັ້ນຕ່ຳທີ່ຕ້ອງມີໃນຕູ້) is the MINIMUM each SKU must have. This:
--   1. Stops, changing nothing, if a B-MM case is already closed on
--      2026-11-27 or has a later day, or if any SKU has sales/returns typed
--      today that its Stock-in does not cover (opening 0 would go below zero).
--   2. Sets every 2026-11-27 opening in B-MM to 0. Stock-in, sales and the
--      rest typed today are kept: staff enter the real count as Stock-in.
--   3. Sets each case's frozen "original stock" to 0 pcs / 0 Baht.
--   4. Saves 235 minimums (a SKU listed twice takes the larger number).
-- Run once in the Supabase SQL editor. One transaction.
-- ============================================================================
begin;

-- 1. Guards.
do $$
declare bad text;
begin
  if (select count(*) from desks where desk_id in ('MM-D01', 'MM-D02', 'MM-D03', 'MM-D04', 'MM-D05', 'MM-D06', 'MM-D07')) <> 7 then
    raise exception 'MM_FIX_NOT_LOADED: the Morning Market cases are not in this database; run the full reset instead';
  end if;
  select string_agg(d.display_name || ' ' || to_char(dd.ledger_date, 'YYYY-MM-DD') || ' (' || dd.status || ')', ', ' order by d.sort_order, dd.ledger_date)
    into bad
    from desk_days dd join desks d using (desk_id)
   where dd.branch_id = 'B-MM'
     and (dd.ledger_date > date '2026-11-27' or (dd.ledger_date = date '2026-11-27' and dd.status = 'done'));
  if bad is not null then
    raise exception 'MM_FIX_BLOCKED: reopen these case days first: %', bad;
  end if;
  select string_agg(d.display_name || ' ' || l.sku_id || ' ' || m.name_lo || ' (' || (l.closing_qty - l.opening_qty) || ')', ', ' order by d.sort_order, l.sku_id)
    into bad
    from daily_stock_ledger l join desks d using (desk_id) join master_sku m using (sku_id)
   where l.ledger_date = date '2026-11-27' and l.branch_id = 'B-MM'
     and l.closing_qty - l.opening_qty < 0;
  if bad is not null then
    raise exception 'MM_FIX_NEGATIVE: with opening 0 these go below zero; enter their Stock-in first: %', bad;
  end if;
end $$;

-- 2. Openings to 0.
update daily_stock_ledger set opening_qty = 0
 where ledger_date = date '2026-11-27' and branch_id = 'B-MM' and opening_qty <> 0;

-- 3. Original stock to 0. Its lock is switched off only for this update.
alter table desks disable trigger trg_desk_origin_immutable;
update desks
   set initial_stock = jsonb_build_object(
         'skus', coalesce((select jsonb_object_agg(k, 0) from jsonb_object_keys(initial_stock -> 'skus') k), '{}'::jsonb),
         'total_pcs', 0, 'total_baht', 0)
 where desk_id in ('MM-D01', 'MM-D02', 'MM-D03', 'MM-D04', 'MM-D05', 'MM-D06', 'MM-D07') and initial_stock is not null;
alter table desks enable trigger trg_desk_origin_immutable;

-- 4. Minimum pieces per SKU for the branch (column E, ຂັ້ນຕ່ຳທີ່ຕ້ອງມີໃນຕູ້). At or
-- below it the app says "Order now". A lead time already set is kept.
on conflict (scope, scope_key, coalesce(branch_id, '*'))
  do update set min_qty = excluded.min_qty, avg_daily_sell = null;

-- Check, then one audit entry.
do $$ begin
  if (select coalesce(sum(opening_qty), 0) from daily_stock_ledger where ledger_date = date '2026-11-27' and branch_id = 'B-MM') <> 0 then
    raise exception 'MM_FIX_CHECK: openings';
  end if;
  if (select count(*) from replenishment_rule r join (values ('MM0001', 30), ('MM0002', 30), ('MM0003', 100), ('MM0004', 80), ('MM0005', 30), ('MM0006', 30), ('MM0007', 30), ('MM0008', 60), ('MM0009', 50), ('MM0010', 50), ('MM0011', 20), ('MM0012', 40), ('MM0013', 150), ('MM0014', 100), ('MM0015', 50), ('MM0016', 20), ('MM0017', 20), ('MM0018', 20), ('MM0019', 20), ('MM0020', 30), ('MM0021', 15), ('MM0022', 10), ('MM0023', 40), ('MM0024', 100), ('MM0025', 100), ('MM0026', 30), ('MM0027', 30), ('MM0028', 30), ('MM0029', 40), ('MM0030', 60), ('MM0031', 60), ('MM0032', 30), ('MM0033', 50), ('MM0034', 40), ('MM0035', 40), ('MM0036', 100), ('MM0037', 100), ('MM0038', 100), ('MM0039', 100), ('MM0040', 50), ('MM0041', 50), ('MM0042', 30), ('MM0043', 40), ('MM0044', 15), ('MM0045', 15), ('MM0046', 20), ('MM0047', 50), ('MM0048', 20), ('MM0049', 50), ('MM0050', 20), ('MM0051', 10), ('MM0052', 10), ('MM0053', 25), ('MM0054', 25), ('MM0055', 20), ('MM0056', 20), ('MM0057', 20), ('MM0058', 20), ('MM0059', 10), ('MM0060', 20), ('MM0061', 20), ('MM0062', 5), ('MM0063', 15), ('MM0064', 20), ('MM0065', 105), ('MM0066', 60), ('MM0067', 50), ('MM0068', 30), ('MM0069', 40), ('MM0070', 30), ('MM0071', 20), ('MM0072', 20), ('MM0073', 20), ('MM0074', 10), ('MM0075', 10), ('MM0076', 20), ('MM0077', 15), ('MM0078', 15), ('MM0079', 15), ('MM0080', 10), ('MM0081', 15), ('MM0082', 5), ('MM0083', 5), ('MM0084', 15), ('MM0085', 10), ('MM0086', 10), ('MM0087', 10), ('MM0088', 10), ('MM0089', 5), ('MM0090', 20), ('MM0091', 70), ('MM0092', 40), ('MM0093', 40), ('MM0094', 10), ('MM0095', 140), ('MM0096', 100), ('MM0097', 50), ('MM0098', 50), ('MM0099', 10), ('MM0100', 10), ('MM0101', 7), ('MM0102', 10), ('MM0103', 20), ('MM0104', 10), ('MM0105', 10), ('MM0106', 10), ('MM0107', 5), ('MM0108', 10), ('MM0109', 10), ('MM0110', 15), ('MM0111', 5), ('MM0112', 5), ('MM0113', 5), ('MM0114', 5), ('MM0115', 10), ('MM0116', 10), ('MM0117', 15), ('MM0118', 15), ('MM0119', 10), ('MM0120', 5), ('MM0121', 10), ('MM0122', 15), ('MM0123', 40), ('MM0124', 5), ('MM0125', 15), ('MM0126', 15), ('MM0127', 15), ('MM0128', 15), ('MM0129', 20), ('MM0130', 60), ('MM0131', 30), ('MM0132', 20), ('MM0133', 15), ('MM0134', 15), ('MM0135', 15), ('MM0136', 15), ('MM0137', 10), ('MM0138', 10), ('MM0139', 70), ('MM0140', 50), ('MM0141', 50), ('MM0142', 100), ('MM0143', 50), ('MM0144', 50), ('MM0145', 40), ('MM0146', 100), ('MM0147', 60), ('MM0148', 90), ('MM0149', 30), ('MM0150', 30), ('MM0151', 20), ('MM0152', 20), ('MM0153', 30), ('MM0154', 20), ('MM0155', 30), ('MM0156', 30), ('MM0157', 50), ('MM0158', 50), ('MM0159', 50), ('MM0160', 50), ('MM0161', 15), ('MM0162', 20), ('MM0163', 15), ('MM0164', 30), ('MM0165', 20), ('MM0166', 30), ('MM0167', 30), ('MM0168', 30), ('MM0169', 10), ('MM0170', 10), ('MM0171', 10), ('MM0172', 20), ('MM0173', 10), ('MM0174', 10), ('MM0175', 20), ('MM0176', 20), ('MM0177', 7), ('MM0178', 5), ('MM0179', 5), ('MM0180', 8), ('MM0181', 10), ('MM0182', 5), ('MM0183', 5), ('MM0184', 5), ('MM0185', 5), ('MM0186', 5), ('MM0187', 3), ('MM0188', 3), ('MM0189', 3), ('MM0190', 3), ('MM0191', 2), ('MM0192', 2), ('MM0193', 2), ('MM0194', 2), ('MM0195', 2), ('MM0196', 2), ('MM0197', 2), ('MM0198', 2), ('MM0199', 2), ('MM0200', 2), ('MM0201', 2), ('MM0202', 2), ('MM0203', 2), ('MM0204', 2), ('MM0205', 2), ('MM0206', 50), ('MM0207', 50), ('MM0208', 50), ('MM0209', 50), ('MM0210', 50), ('MM0211', 30), ('MM0212', 20), ('MM0213', 4), ('MM0214', 3), ('MM0215', 3), ('MM0216', 6), ('MM0217', 10), ('MM0218', 10), ('MM0219', 3), ('MM0220', 5), ('MM0221', 5), ('MM0222', 10), ('MM0223', 10), ('MM0224', 10), ('MM0225', 10), ('MM0226', 10), ('MM0227', 10), ('MM0228', 5), ('MM0229', 50), ('MM0230', 50), ('MM0231', 20), ('MM0232', 20), ('MM0233', 20), ('MM0234', 50), ('MM0235', 20)) v(sku_id, q)
        on r.scope = 'sku' and r.scope_key = v.sku_id and r.branch_id = 'B-MM' and r.min_qty = v.q) <> 235 then
    raise exception 'MM_FIX_CHECK: minimums';
  end if;
end $$;
values ('system', 'data.min_reset', 'B-MM', jsonb_build_object('source', 'ລາຍລະອຽດເຄື່ອງຕູ້_1-7 morning market actual.xlsx', 'date', '2026-11-27',
        'openings', 0, 'minimums', 235));

commit;

-- Per case: SKUs, opening and current pieces, and the minimums it should hold.
select d.display_name as case_name, count(*) as skus,
       sum(l.opening_qty) as opening_pcs, sum(l.closing_qty) as now_pcs,
       sum(r.min_qty) as min_pcs
  from daily_stock_ledger l
  join desks d using (desk_id)
  left join replenishment_rule r on r.scope = 'sku' and r.scope_key = l.sku_id and r.branch_id = l.branch_id
 where l.ledger_date = date '2026-11-27' and l.branch_id = 'B-MM'
 group by d.display_name, d.sort_order order by d.sort_order;
